mapper.select:
SELECT COUNT(*) FROM JL_COMMUNITY_POST p WHERE p.status = 'ACTIVE'
AND p.category = #{category}
AND (LOWER(p.title) LIKE LOWER('%' || #{query} || '%') OR LOWER(p.body) LIKE LOWER('%' || #{query} || '%'))

SELECT id, category, title, body, created_at, view_count, comment_count, like_count FROM ( SELECT p.id, p.category, p.title, p.body, p.created_at, p.view_count, (SELECT COUNT(*) FROM JL_COMMUNITY_COMMENT c WHERE c.post_id = p.id AND c.status = 'ACTIVE') AS comment_count, (SELECT COUNT(*) FROM JL_COMMUNITY_LIKE l WHERE l.post_id = p.id) AS like_count, ROW_NUMBER() OVER (ORDER BY p.updated_at DESC, p.id DESC) AS rn FROM JL_COMMUNITY_POST p WHERE p.status = 'ACTIVE'
AND p.category = #{category}
AND (LOWER(p.title) LIKE LOWER('%' || #{query} || '%') OR LOWER(p.body) LIKE LOWER('%' || #{query} || '%'))
) WHERE rn > #{offset} AND rn <= #{offset} + #{limit} ORDER BY rn

SELECT COUNT(*) FROM JL_COMMUNITY_POST p JOIN JL_MEMBER m ON m.id = p.member_id
AND p.category = #{category}
AND (LOWER(p.title) LIKE LOWER('%' || #{query} || '%') OR LOWER(p.body) LIKE LOWER('%' || #{query} || '%'))

SELECT id, category, title, status, created_at, updated_at, view_count, login_id, comment_count, like_count FROM ( SELECT p.id, p.category, p.title, p.status, p.created_at, p.updated_at, p.view_count, m.login_id, (SELECT COUNT(*) FROM JL_COMMUNITY_COMMENT c WHERE c.post_id = p.id AND c.status = 'ACTIVE') AS comment_count, (SELECT COUNT(*) FROM JL_COMMUNITY_LIKE l WHERE l.post_id = p.id) AS like_count, ROW_NUMBER() OVER (ORDER BY p.id DESC) AS rn FROM JL_COMMUNITY_POST p JOIN JL_MEMBER m ON m.id = p.member_id
AND p.category = #{category}
AND (LOWER(p.title) LIKE LOWER('%' || #{query} || '%') OR LOWER(p.body) LIKE LOWER('%' || #{query} || '%'))
) WHERE rn > #{offset} AND rn <= #{offset} + #{limit} ORDER BY rn
